function useFadeIn() {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) el.classList.add('moku-fade--visible'); },
      { threshold: 0.1 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return ref;
}

function FadeIn({ children, className = '' }) {
  const ref = useFadeIn();
  return <div ref={ref} className={`moku-fade ${className}`}>{children}</div>;
}

function FaqItem({ q, a }) {
  const [open, setOpen] = useState(false);
  return (
    <div className={`moku-faq-item${open ? ' moku-faq-item--open' : ''}`}>
      <button className="moku-faq-q" onClick={() => setOpen(!open)}>
        <span className="q-mark">Q</span>
        {q}
        <span className="arrow">▼</span>
      </button>
      <div className="moku-faq-a">{a}</div>
    </div>
  );
}

